add_action( 'template_redirect', 'perfectpixel_redirect_404_home', 99 );

function perfectpixel_redirect_404_home() {
	if ( ! is_404() || is_admin() || wp_doing_ajax() || ( defined( 'REST_REQUEST' ) && REST_REQUEST ) ) {
		return;
	}
	// Missing files (images, scripts, styles…) keep their normal 404.
	$path = (string) wp_parse_url( isset( $_SERVER['REQUEST_URI'] ) ? wp_unslash( $_SERVER['REQUEST_URI'] ) : '', PHP_URL_PATH );
	if ( preg_match( '/\.[a-z0-9]{2,5}$/i', $path ) ) {
		return;
	}
	$target = trim( '{{redirect_404_url}}' );
	$target = '' !== $target ? $target : home_url( '/' );
	$status = 301 === (int) '{{redirect_404_status}}' ? 301 : 302;
	wp_safe_redirect( $target, $status );
	exit;
}
